namespace Acme.Shipments;

public enum ShipmentStatus
{
    Pending,
    InTransit,
    Delivered,
    Returned,
}

public enum Carrier
{
    Yamato,
    Sagawa,
    JapanPost,
}

public sealed record Shipment(int Id, string TrackingNumber, ShipmentStatus Status, Carrier Carrier);

using Acme.Shipments;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<IShipmentRepository, InMemoryShipmentRepository>();

var app = builder.Build();

app.MapGet("/shipments/{id:int}", async (int id, IShipmentRepository shipments) =>
    await shipments.FindAsync(id) is { } shipment
        ? Results.Ok(shipment)
        : Results.NotFound());

app.Run();

