using System.Text.Json.Serialization;

namespace Acme.Shipments;

public sealed record Shipment(
    int Id,
    string TrackingNumber,
    [property: JsonConverter(typeof(JsonStringEnumConverter<ShipmentStatus>))] ShipmentStatus Status,
    Carrier Carrier);

// src/Program.cs
using System.Text.Json.Serialization;
using Acme.Shipments;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<IShipmentRepository, InMemoryShipmentRepository>();
builder.Services.ConfigureHttpJsonOptions(options =>
    options.SerializerOptions.Converters.Add(new JsonStringEnumConverter()));

// src/Shipments/Shipment.cs
public sealed record Shipment(int Id, string TrackingNumber, ShipmentStatus Status, Carrier Carrier);
